using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalNormalRestrictionDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalNormalRestriction.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The whole original positive annihilator cone has an interior constant-one lift and surjects onto the full affine chart; uniqueness of the complete common confirmer forces actual restriction rigidity.",
        H("Whole original normal restriction"), Blocks(
        Paragraph(Text("Keep the original finite dimensional real normed V, its entire closed generating cone C, strictly positive unit u, normalized base K, all extreme points P and all effects between zero and u. EB3 supplies an injective affine chart of the entire closed three-ball for every pure label. Inj concerns equality of whole exclusion sets. No Pair, closedness of P, common inner product, continuity of the chart family, retraction or matrix representation is assumed.")),
        Describe.Lean(DescribeId.Create("original-normal-restriction"),
            DeclarationHandle.Create(Owner + "original_normal_restriction"),
            H("Full affine restriction and the singleton complete confirmer fiber"),
            StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("For every original pure p and every complete three-ball chart a, N consists of every original continuous real-linear functional nonnegative on all of C and zero at p. Finite dimensionality identifies these with all real-linear functionals. L is the actual span of N. R sends h in L to its composition with the entire affine chart, in the full space of affine functions on the chart vector space. R is onto and dim L is at least four.")),
                Paragraph(Text("The constant-one slice H consists of the members of N equal to one at every point of the full chart ball. It equals the set of complements u-e of all members of the complete original common confirmer fiber A(p): e is an original proper effect, e(p)=1, and e vanishes on the entire D(p). This is different from the larger fiber of effects merely taking value one at p. The all-C upper bound for H uses the original positive-annihilator maximum theorem and homogenization on the whole cone.")),
                Paragraph(Text("H meets the relative interior of N. The theorem supplies both intrinsicInterior membership in the original dual and an actual open neighborhood in L. In L the full normal cone spans the entire space and is convex, so its interior is nonempty. Add a genuine constant-one normal to an interior member, making the chart-center value strictly positive. The whole slope-body inradius and original full-ball formula provide a positive normal whose scaled slope cancels the interior member's slope. Cone addition preserves the neighborhood, and positive normalization gives the required constant-one interior member. The signed-axis construction and its radius supply this slope correction.")),
                Paragraph(Text("If the entire A(p) is the singleton containing ep, the interior member is exactly gp=u-ep. For every direction k in the actual kernel of R, its neighborhood gives feasible gp+t k and gp-t k in the whole N for a positive t. Both remain constant one on the whole ball. The same all-C maximum bound puts both complements in A(p), so uniqueness forces k=0. The constructed linear equivalence has underlying linear map exactly R, R is bijective and dim L equals four. Label injectivity is used only to obtain SingleLabel for the slope-body inradius theorem; it never supplies effect uniqueness."))),
            DescribeRole.Theorem),
        Paragraph(Text("For an actual model take V to be all complex Hermitian three by three matrices, C the entire positive semidefinite cone, and u the trace. HermitianExclusionKernel identifies the exclusion defined by all original proper real-linear effects with all positive trace-one matrices annihilating the label vector. HermitianExclusionBall.all_pure_charts supplies a globally injective affine chart of the whole closed three-ball for every actual extreme point. The cone is closed, trace is strictly positive away from zero, and all-density tomography gives generation of the whole real carrier. Equal whole exclusions force equal pure labels: the mixed state (I-p)/2 in D(p) annihilates the vector of q, giving pq=q; reversing the labels and taking adjoints gives p=q. Thus the same entire model pays closedness, strictness, generation, EB3 and Inj together. Substituting these data in original_normal_restriction gives every stated conclusion for every original pure p and every complete dimension-three chart. The common-confirmation singleton remains the premise of the isomorphism branch; no occurrence of that branch is asserted.")),
        Paragraph(Text("Retain the same original V, C, u, K, P, full effect interval, EB3 and Inj. Let F=D(p) be the entire exclusion chart w ↦ c+B w and G=D(s) the entire exclusion chart z ↦ cs+A z, with independent three-dimensional Euclidean coordinate spaces. Fix M>0, a unit F-coordinate n, q=c+B n, r=c-B n, a pure s and y=cs+A eta in G with norm(eta)≤1. Assume the actual vector identity q-r=M(s-y), and that every original effect has ordered difference at most M between any two points of F. These are sufficient premises; neither M<1 nor uniqueness of the complete common confirmer fiber is needed. In the original strict application, M is the actual globally maximal width W(F), 0<M<1, and b is the same proper attaining original effect with b(s)=1 and b(y)=0. OriginalWidthContact.original_width_contact supplies its unique original contact pair, with the orientation and endpoints just specified. ExclusionWidthCompactness.effect_difference_le_width supplies the full-effect bound from that actual width. This conditional substitution keeps the original width, effect and contacts together.")),
        Paragraph(Text("For this application write N_s for the entire original positive annihilator cone at s and H_s=span(N_s); H_s is the normal span called L above, not the constant-one slice called H above. Every h in H_s vanishes at s. Finite dimensionality identifies the continuous and algebraic real duals. Define the actual whole-G restriction coordinates R_s h=(alpha,v) by h(cs+A z)=alpha+inner(v,z), and the actual whole-F slope S_F h by h(c+B w)=h(c)+inner(S_F h,w). SingleLabelNormalBody.slope_formula supplies these affine coordinate identities. The maps are restrictions of the original functionals to the two entire charts; no substitute maps or kernel inclusion are assumed. The conclusion of original_normal_restriction at s and G gives surjectivity onto all affine G functions, hence onto all pairs (alpha,v), and a g0 in the interior of N_s relative to H_s with R_s g0=(1,0).")),
        Paragraph(Text("Every g in N_s with R_s g=(1,0) is an original effect: the whole-cone bound in original_normal_restriction gives 0≤g≤u, and a=u-g belongs to the complete common confirmer fiber at s. Thus a(s)=1 and a(y)=0 for the same y in G. Evaluation on the fixed chord gives a(q)-a(r)=M. The full-effect bound and WholePairBallConfirmation.affine_zero_antipode, together with SingleLabelNormalBody.slope_formula, give S_F a=(M/2)n. Since u is constant on F, S_F g=-(M/2)n for every member of the entire constant-one positive fiber. This uses the common confirmer slope consequence; no additional face-transfer conclusion is needed.")),
        Paragraph(Text("For any k in ker(R_s), the actual interior neighborhood of g0 contains g0+t k and g0-t k for some t>0. Both belong to N_s and retain R_s=(1,0), so their F slopes both equal -(M/2)n. Subtracting and cancelling the nonzero scalar gives S_F k=0. Hence ker(R_s) is contained in ker(S_F). Apply the pinned Mathlib LinearMap.liftOfSurjective API to the actual surjective R_s and this inclusion: there is a linear T_s from the G restriction-coordinate space to the F slope space with S_F=T_s composed with R_s. Surjectivity makes T_s unique, and evaluation at g0 fixes T_s(1,0)=-(M/2)n.")),
        Paragraph(Text("For every signed h in H_s, applying h to the same chord and using h(s)=0 gives 2 inner(n,S_F h)=-M h(y)=-M(alpha+inner(eta,v)), where R_s h=(alpha,v). Surjectivity transfers this equality to every pair (alpha,v). Define L(v)=T_s(0,v)+(M/2)inner(eta,v)n. It is linear and lies in the actual F-coordinate orthogonal complement n-perp, since norm(n)=1. Linearity and the fixed value at (1,0) give the full formula T_s(alpha,v)=-(M/2)(alpha+inner(eta,v))n+L(v), for all alpha and v. The formula at alpha=0 determines L uniquely, including as a map into that orthogonal-complement subtype. There is no transverse term in the constant coordinate.")),
        Paragraph(Text("Let D be the real span of every difference x-z with x,z in the entire F, let span(G) be the real linear span of the entire G in V, and let ann denote annihilation in the original real dual. Whole-ball affine extensionality gives the exact identities ker(R_s)=H_s intersect ann(span(G)) and ker(S_F)=H_s intersect ann(D). As subspaces of H_s these intersections are comaps under its inclusion into the original dual. Define H_s-perp to consist of every x in V annihilated by every h in H_s. The kernel inclusion says that D annihilates H_s intersect ann(span(G)). The pinned finite-dimensional dualCoannihilator_inf and double-annihilator identities identify its preannihilator with H_s-perp+span(G). Therefore D is contained in span(G)+H_s-perp. Both identities and this inclusion concern the whole original carrier and charts.")),
        Paragraph(Text("The same full Hermitian three by three PSD/trace model provides a joint application with M=1. Take p to be the e0 rank-one projector, s=q the e1 projector, y=r the e2 projector, and b(X) its e1 diagonal entry. HermitianExclusionKernel.exclusion_iff_kernel identifies the entire exclusions, including mixed states; HermitianExclusionBall.all_pure_charts supplies whole charts for every actual pure label. Choose n and eta in those same F=D(p) and G=D(s) charts for q and y. The same b is proper, b(s)=1, b(y)=0, q-r=s-y, W(F)=1 and every pure exclusion width is at most one. OriginalWidthContact identifies that same unique original contact pair. Thus the model pays the full cone, all effects, all pure labels, both whole charts, global Inj and the actual R_s and S_F together, and the preceding inference applies to them.")),
        Paragraph(Text("The factor and carrier conclusions are a composition of the cited existing results and pinned linear-factor and annihilator APIs. The strict original application is conditional: no joint model with 0<M<1 and no impossibility proof for that branch is supplied. The native joint instance has M=1 only. No general injectivity of R_s, positive T_s, positive lift of arbitrary signed coordinates, cross-chart isometry, global common-confirmer uniqueness or density conclusion follows here. If the complete common confirmer fiber at s is additionally a singleton, the earlier isomorphism branch already supplies R_s inverse and T_s=S_F composed with that inverse. The statement is mathematical, without a physical realization or literature-priority claim.")))));
}
